import type { FetchErrorCode } from './errors.js';
import type { PageRole } from './hiring.js';

/**
 * What the research layer hands to later pipeline stages.
 *
 * Provenance matters: `text`, `title`, `headings` and `interview_mentions` are OBSERVED, copied
 * from pages that were actually fetched. `role`, `classification` and `hiring` are INFERRED by a
 * transparent heuristic and carry the evidence that produced them. Nothing here is generated by a
 * model, and all page-derived text is untrusted data, never instructions.
 */

export interface SourcePage {
  /** Final URL after redirects. */
  url: string;
  requested_url: string;
  title: string;
  description: string;
  headings: string[];
  /** Readable text, whitespace-normalised, at most 30,000 characters. */
  text: string;
  fetched_at: string;
  status: number;
  content_type: string;
  /** Link distance from the company URL (0 = the company URL itself). */
  depth: number;
  role: PageRole;
  classification: {
    role: Exclude<PageRole, 'home'>;
    hiring_score: number;
    process_score: number;
    evidence: string[];
  };
  /** Sentences quoted verbatim from `text` that mention interviewing. */
  interview_mentions: string[];
  links_found: number;
  /** True when the page was larger than the size limit and only its beginning was read. */
  truncated: boolean;
  content_hash: string;
  provenance: 'observed';
}

export interface SourceFailure {
  url: string;
  code: FetchErrorCode;
  message: string;
  status?: number;
  attempts: number;
}

export interface SkippedSource {
  url: string;
  reason: 'robots' | 'duplicate-content' | 'duplicate-url';
  duplicate_of?: string;
}

export interface RobotsSummary {
  host: string;
  url: string;
  status: 'found' | 'not-found' | 'unreachable';
  crawl_delay_ms: number | null;
}

/**
 * ok                 the company URL was fetched and nothing went wrong
 * partial            the company URL was fetched but at least one other page failed
 * unreachable        the company URL itself could not be fetched
 * blocked-by-robots  robots.txt forbids crawling (or could not be read), so nothing was fetched
 * rejected           the URL is invalid or points somewhere that is not allowed
 */
export type CrawlStatus = 'ok' | 'partial' | 'unreachable' | 'blocked-by-robots' | 'rejected';

export interface CrawlResult {
  company_url: string;
  status: CrawlStatus;
  pages: SourcePage[];
  failures: SourceFailure[];
  skipped: SkippedSource[];
  robots: RobotsSummary[];
  hiring: {
    found: boolean;
    /** True when a fetched page describes the interview process itself. */
    process_found: boolean;
    /** Hiring pages, strongest evidence first. */
    page_urls: string[];
    method: 'content-heuristic';
  };
  /** Plain-language statements of what could not be done. Empty when nothing was limited. */
  limitations: string[];
  stats: {
    requests: number;
    pages_fetched: number;
    elapsed_ms: number;
    budget_exhausted: 'pages' | 'time' | null;
  };
}
